-- 빈 DB 최초 생성용. psql -f database/schema.sql로 실행합니다.
-- 실제 테이블 정의는 schema/ 안에서 수정하세요. 기존 DB에는 재실행하지 않습니다.
BEGIN;
SET LOCAL search_path TO public;
-- ENUM은 테이블보다 먼저 생성합니다. schema.sql에서 이 파일을 가장 먼저 실행합니다.
-- 값 변경 시 기존 DB용 migrations SQL도 함께 작성하세요.

-- 기관 유형
CREATE TYPE agency_type_enum AS ENUM (
    'FIRE',
    'POLICE',
    'ROAD_MANAGEMENT',
    'LOCAL_GOVERNMENT'
);

-- 사용자 내부 역할 (화면 명칭과 구분)
CREATE TYPE user_role_enum AS ENUM (
    'CONTROL_ADMIN',
    'AGENCY_STAFF',
    'RESPONDER'
);

-- CCTV 연결 상태
CREATE TYPE connection_status_enum AS ENUM (
    'CONNECTED',
    'DISCONNECTED',
    'RECONNECTING'
);

-- 영상 품질
CREATE TYPE video_quality_enum AS ENUM (
    'GOOD',
    'LOW',
    'UNAVAILABLE'
);

-- 분석 프로세스 상태
CREATE TYPE analysis_status_enum AS ENUM (
    'RUNNING',
    'STOPPED',
    'ERROR'
);

-- ON 상태에서의 감시 모드 (OFF는 is_monitored=false)
CREATE TYPE monitored_mode_enum AS ENUM (
    'BASE',
    'ALERT',
    'POST_ALERT',
    'VERIFY'
);

-- 사건 처리 상태
CREATE TYPE incident_status_enum AS ENUM (
    'DETECTED',
    'FALSE_POSITIVE',
    'CONFIRMED',
    'SENT'
);

-- 기상특보 상태
CREATE TYPE weather_status_enum AS ENUM (
    'ACTIVE',
    'ENDED'
);

-- 기관 추천/전달 상태
CREATE TYPE recommendation_status_enum AS ENUM (
    'RECOMMENDED',
    'DELIVERED'
);

-- 추가 지원요청 유형
CREATE TYPE support_type_enum AS ENUM (
    'PERSONNEL',
    'EQUIPMENT',
    'TRAFFIC_CONTROL',
    'OTHER'
);
CREATE TABLE region (
    region_code VARCHAR(100) PRIMARY KEY,
    sido_name VARCHAR(100) NOT NULL,
    sigungu_name VARCHAR(100) NOT NULL,
    weather_region_code VARCHAR(500)
);
COMMENT ON TABLE region IS '지역코드';
COMMENT ON COLUMN region.region_code IS '지역코드 ID';
COMMENT ON COLUMN region.sido_name IS '시도 이름';
COMMENT ON COLUMN region.sigungu_name IS '시군구 이름';
COMMENT ON COLUMN region.weather_region_code IS '기상특보 API 지역코드';
CREATE TABLE agencies (
    id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    name VARCHAR(150) NOT NULL,
    agency_type agency_type_enum NOT NULL,
    address VARCHAR(255),
    latitude DECIMAL(10,7) NOT NULL,
    longitude DECIMAL(10,7) NOT NULL,
    phone VARCHAR(30) NOT NULL,
    region_code VARCHAR(100) NOT NULL REFERENCES region(region_code)
);
COMMENT ON TABLE agencies IS '대응 후보 기관';
COMMENT ON COLUMN agencies.id IS '기관 ID';
COMMENT ON COLUMN agencies.name IS '기관명';
COMMENT ON COLUMN agencies.agency_type IS '기관 유형';
COMMENT ON COLUMN agencies.address IS '기관 주소';
COMMENT ON COLUMN agencies.latitude IS '기관 위치 위도';
COMMENT ON COLUMN agencies.longitude IS '기관 위치 경도';
COMMENT ON COLUMN agencies.phone IS '대표 연락처';
COMMENT ON COLUMN agencies.region_code IS '지역코드 ID';
CREATE TABLE users (
    id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    email VARCHAR(255) NOT NULL,
    password_hash VARCHAR(255) NOT NULL,
    name VARCHAR(100) NOT NULL,
    role user_role_enum NOT NULL,
    is_active BOOLEAN NOT NULL DEFAULT TRUE,
    agency_id BIGINT REFERENCES agencies(id),
    notification_enabled BOOLEAN NOT NULL DEFAULT TRUE
);
COMMENT ON TABLE users IS '관리자·출동요원';
COMMENT ON COLUMN users.id IS '사용자 ID';
COMMENT ON COLUMN users.email IS '이메일';
COMMENT ON COLUMN users.password_hash IS '비밀번호 해시';
COMMENT ON COLUMN users.name IS '이름';
COMMENT ON COLUMN users.role IS '역할';
COMMENT ON COLUMN users.is_active IS '활성 여부';
COMMENT ON COLUMN users.agency_id IS '기관 ID';
COMMENT ON COLUMN users.notification_enabled IS '알림 수신 여부';
CREATE TABLE cctvs (
    id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    external_cctv_id VARCHAR(100) NOT NULL,
    name VARCHAR(150) NOT NULL,
    provider VARCHAR(100) NOT NULL,
    address VARCHAR(255),
    latitude DECIMAL(10,7) NOT NULL,
    longitude DECIMAL(10,7) NOT NULL,
    stream_url VARCHAR(500),
    is_monitored BOOLEAN NOT NULL DEFAULT FALSE,
    connection_status connection_status_enum NOT NULL DEFAULT 'DISCONNECTED',
    video_quality_status video_quality_enum,
    analysis_status analysis_status_enum,
    last_frame_at TIMESTAMP WITHOUT TIME ZONE,
    region_code VARCHAR(100) REFERENCES region(region_code),
    monitored_mode monitored_mode_enum
);
COMMENT ON TABLE cctvs IS 'CCTV 기본정보·현재 상태';
COMMENT ON COLUMN cctvs.id IS 'CCTV ID';
COMMENT ON COLUMN cctvs.external_cctv_id IS '외부 CCTV ID';
COMMENT ON COLUMN cctvs.name IS 'CCTV명';
COMMENT ON COLUMN cctvs.provider IS '제공 기관';
COMMENT ON COLUMN cctvs.address IS '주소';
COMMENT ON COLUMN cctvs.latitude IS '위도';
COMMENT ON COLUMN cctvs.longitude IS '경도';
COMMENT ON COLUMN cctvs.stream_url IS '스트리밍 URL';
COMMENT ON COLUMN cctvs.is_monitored IS '상시 감시 여부';
COMMENT ON COLUMN cctvs.connection_status IS '연결 상태';
COMMENT ON COLUMN cctvs.video_quality_status IS '영상 품질 상태';
COMMENT ON COLUMN cctvs.analysis_status IS '분석 상태';
COMMENT ON COLUMN cctvs.last_frame_at IS '마지막 프레임 수신 일시';
COMMENT ON COLUMN cctvs.region_code IS '지역코드 ID';
COMMENT ON COLUMN cctvs.monitored_mode IS '현재 감시 상태';
CREATE TABLE monitoring_settings (
    id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    base_analysis_interval_sec INT NOT NULL,
    alert_analysis_interval_sec INT NOT NULL,
    verify_analysis_interval_sec INT NOT NULL,
    candidate_confidence_threshold DECIMAL(5,4) NOT NULL,
    candidate_min_detection_count INT NOT NULL,
    temporal_validation_sec INT NOT NULL,
    incident_confidence_threshold DECIMAL(5,4) NOT NULL,
    reconnect_interval_sec INT NOT NULL,
    max_reconnect_attempts INT NOT NULL,
    quality_threshold DECIMAL(5,4) NOT NULL,
    updated_by BIGINT REFERENCES users(id),
    updated_at TIMESTAMP WITHOUT TIME ZONE NOT NULL DEFAULT CURRENT_TIMESTAMP
);
COMMENT ON TABLE monitoring_settings IS '감시·분석 기준';
COMMENT ON COLUMN monitoring_settings.id IS '감시 설정 ID';
COMMENT ON COLUMN monitoring_settings.base_analysis_interval_sec IS '기본 분석 주기(초)';
COMMENT ON COLUMN monitoring_settings.alert_analysis_interval_sec IS '특보 분석 주기(초)';
COMMENT ON COLUMN monitoring_settings.verify_analysis_interval_sec IS '집중 분석 주기(초)';
COMMENT ON COLUMN monitoring_settings.candidate_confidence_threshold IS '후보 신뢰도 임계값';
COMMENT ON COLUMN monitoring_settings.candidate_min_detection_count IS '후보 최소 탐지 횟수';
COMMENT ON COLUMN monitoring_settings.temporal_validation_sec IS '시간 연속성 검증 기준';
COMMENT ON COLUMN monitoring_settings.incident_confidence_threshold IS '사건 확정 신뢰도 임계값';
COMMENT ON COLUMN monitoring_settings.reconnect_interval_sec IS '재연결 주기(초)';
COMMENT ON COLUMN monitoring_settings.max_reconnect_attempts IS '최대 재연결 시도 횟수';
COMMENT ON COLUMN monitoring_settings.quality_threshold IS '영상 품질 임계값';
COMMENT ON COLUMN monitoring_settings.updated_by IS '수정 사용자 ID';
COMMENT ON COLUMN monitoring_settings.updated_at IS '수정 일시';
CREATE TABLE incidents (
    id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    incident_no VARCHAR(50) NOT NULL,
    cctv_id BIGINT NOT NULL REFERENCES cctvs(id),
    hazard_type VARCHAR(50) NOT NULL,
    confidence DECIMAL(5,4) NOT NULL,
    model_version VARCHAR(100) NOT NULL,
    detection_image_path VARCHAR(500) NOT NULL,
    detection_bbox_json JSON NOT NULL,
    detection_duration_sec INT NOT NULL,
    dedup_key VARCHAR(255) NOT NULL,
    status incident_status_enum NOT NULL DEFAULT 'DETECTED',
    detected_at TIMESTAMP WITHOUT TIME ZONE NOT NULL DEFAULT CURRENT_TIMESTAMP,
    last_detected_at TIMESTAMP WITHOUT TIME ZONE NOT NULL DEFAULT CURRENT_TIMESTAMP
);
COMMENT ON TABLE incidents IS '확정 사건';
COMMENT ON COLUMN incidents.id IS '확정 사건 ID';
COMMENT ON COLUMN incidents.incident_no IS '사건 번호';
COMMENT ON COLUMN incidents.cctv_id IS 'CCTV ID';
COMMENT ON COLUMN incidents.hazard_type IS '재난 유형';
COMMENT ON COLUMN incidents.confidence IS '탐지 신뢰도';
COMMENT ON COLUMN incidents.model_version IS '모델 버전';
COMMENT ON COLUMN incidents.detection_image_path IS '탐지 이미지 경로';
COMMENT ON COLUMN incidents.detection_bbox_json IS '탐지 바운딩박스 JSON';
COMMENT ON COLUMN incidents.detection_duration_sec IS '탐지 지속시간(초)';
COMMENT ON COLUMN incidents.dedup_key IS '중복 판별 키';
COMMENT ON COLUMN incidents.status IS '사건 상태';
COMMENT ON COLUMN incidents.detected_at IS '탐지 일시';
COMMENT ON COLUMN incidents.last_detected_at IS '마지막 탐지 일시';
CREATE TABLE weather_alerts (
    id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    external_alert_id VARCHAR(100) NOT NULL,
    alert_type VARCHAR(50) NOT NULL,
    alert_level VARCHAR(50) NOT NULL,
    title VARCHAR(255) NOT NULL,
    issued_at TIMESTAMP WITHOUT TIME ZONE NOT NULL,
    ended_at TIMESTAMP WITHOUT TIME ZONE,
    status weather_status_enum NOT NULL DEFAULT 'ACTIVE',
    raw_data_json JSON NOT NULL,
    region_code VARCHAR(100) NOT NULL REFERENCES region(region_code)
);
COMMENT ON TABLE weather_alerts IS '기상특보';
COMMENT ON COLUMN weather_alerts.id IS '기상특보 ID';
COMMENT ON COLUMN weather_alerts.external_alert_id IS '외부 특보 ID';
COMMENT ON COLUMN weather_alerts.alert_type IS '특보 유형';
COMMENT ON COLUMN weather_alerts.alert_level IS '특보 단계';
COMMENT ON COLUMN weather_alerts.title IS '특보 제목';
COMMENT ON COLUMN weather_alerts.issued_at IS '특보 발표 일시';
COMMENT ON COLUMN weather_alerts.ended_at IS '특보 해제 일시';
COMMENT ON COLUMN weather_alerts.status IS '특보 상태';
COMMENT ON COLUMN weather_alerts.raw_data_json IS '원본 데이터 JSON';
COMMENT ON COLUMN weather_alerts.region_code IS '지역코드 ID';
CREATE TABLE incident_contexts (
    id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    incident_id BIGINT NOT NULL REFERENCES incidents(id),
    weather_alert_id BIGINT REFERENCES weather_alerts(id),
    rainfall_mm DECIMAL(7,2),
    water_level_m DECIMAL(7,2),
    traffic_level VARCHAR(30),
    blocked_lane_count INT,
    road_type VARCHAR(50),
    nearby_facility_type VARCHAR(100),
    nearby_facility_distance_m INT,
    past_disaster_count INT,
    raw_context_json JSON NOT NULL,
    captured_at TIMESTAMP WITHOUT TIME ZONE NOT NULL DEFAULT CURRENT_TIMESTAMP
);
COMMENT ON TABLE incident_contexts IS '외부 상황 스냅샷';
COMMENT ON COLUMN incident_contexts.id IS '외부 상황 스냅샷 ID';
COMMENT ON COLUMN incident_contexts.incident_id IS '사건 ID';
COMMENT ON COLUMN incident_contexts.weather_alert_id IS '기상특보 ID';
COMMENT ON COLUMN incident_contexts.rainfall_mm IS '강수량(mm)';
COMMENT ON COLUMN incident_contexts.water_level_m IS '수위(m)';
COMMENT ON COLUMN incident_contexts.traffic_level IS '교통 수준';
COMMENT ON COLUMN incident_contexts.blocked_lane_count IS '차단 차로 수';
COMMENT ON COLUMN incident_contexts.road_type IS '도로 유형';
COMMENT ON COLUMN incident_contexts.nearby_facility_type IS '인근 시설 유형';
COMMENT ON COLUMN incident_contexts.nearby_facility_distance_m IS '인근 시설 거리(m)';
COMMENT ON COLUMN incident_contexts.past_disaster_count IS '주변 지역 과거 재난 횟수';
COMMENT ON COLUMN incident_contexts.raw_context_json IS '외부 상황 원본 JSON';
COMMENT ON COLUMN incident_contexts.captured_at IS '수집 일시';
CREATE TABLE incident_assessments (
    id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    incident_id BIGINT NOT NULL REFERENCES incidents(id),
    risk_score DECIMAL(6,2) NOT NULL,
    risk_level VARCHAR(30) NOT NULL,
    risk_breakdown_json JSON NOT NULL,
    priority_score DECIMAL(6,2) NOT NULL,
    priority VARCHAR(30) NOT NULL,
    priority_breakdown_json JSON NOT NULL,
    rule_version VARCHAR(50) NOT NULL
);
COMMENT ON TABLE incident_assessments IS '위험도·우선순위';
COMMENT ON COLUMN incident_assessments.id IS '위험도·우선순위 평가 ID';
COMMENT ON COLUMN incident_assessments.incident_id IS '사건 ID';
COMMENT ON COLUMN incident_assessments.risk_score IS '위험도 점수';
COMMENT ON COLUMN incident_assessments.risk_level IS '위험도 등급';
COMMENT ON COLUMN incident_assessments.risk_breakdown_json IS '위험도 세부 내역 JSON';
COMMENT ON COLUMN incident_assessments.priority_score IS '우선순위 점수';
COMMENT ON COLUMN incident_assessments.priority IS '대응 우선순위';
COMMENT ON COLUMN incident_assessments.priority_breakdown_json IS '우선순위 세부 내역 JSON';
COMMENT ON COLUMN incident_assessments.rule_version IS '규칙 버전';
CREATE TABLE incident_agency_recommendations (
    id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    recommendation_rank INT NOT NULL,
    recommendation_score DECIMAL(6,2) NOT NULL,
    score_breakdown_json JSON NOT NULL,
    rule_version VARCHAR(50) NOT NULL,
    recommendation_status recommendation_status_enum NOT NULL DEFAULT 'RECOMMENDED',
    recommended_at TIMESTAMP WITHOUT TIME ZONE NOT NULL DEFAULT CURRENT_TIMESTAMP,
    incident_id BIGINT NOT NULL REFERENCES incidents(id),
    agency_id BIGINT NOT NULL REFERENCES agencies(id)
);
COMMENT ON TABLE incident_agency_recommendations IS '사건별 추천 기관';
COMMENT ON COLUMN incident_agency_recommendations.id IS '기관 추천 ID';
COMMENT ON COLUMN incident_agency_recommendations.recommendation_rank IS '기관 추천 순위';
COMMENT ON COLUMN incident_agency_recommendations.recommendation_score IS '기관 추천 점수';
COMMENT ON COLUMN incident_agency_recommendations.score_breakdown_json IS '기관 추천 세부 점수';
COMMENT ON COLUMN incident_agency_recommendations.rule_version IS '기관 추천 규칙 버전';
COMMENT ON COLUMN incident_agency_recommendations.recommendation_status IS '기관 추천 처리 상태';
COMMENT ON COLUMN incident_agency_recommendations.recommended_at IS '기관 추천 시각';
COMMENT ON COLUMN incident_agency_recommendations.incident_id IS '확정 사건 ID';
COMMENT ON COLUMN incident_agency_recommendations.agency_id IS '기관 ID · 원본 BIGBT 오기를 BIGINT로 수정';
CREATE TABLE route_evaluations (
    id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    rule_version VARCHAR(50) NOT NULL,
    created_at TIMESTAMP WITHOUT TIME ZONE NOT NULL DEFAULT CURRENT_TIMESTAMP,
    agency_recommendation_id BIGINT NOT NULL REFERENCES incident_agency_recommendations(id)
);
COMMENT ON TABLE route_evaluations IS '경로 평가 실행';
COMMENT ON COLUMN route_evaluations.id IS '경로 평가 ID';
COMMENT ON COLUMN route_evaluations.rule_version IS '규칙 버전';
COMMENT ON COLUMN route_evaluations.created_at IS '생성 일시';
COMMENT ON COLUMN route_evaluations.agency_recommendation_id IS '기관 추천 ID';
CREATE TABLE route_candidates (
    id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    route_name VARCHAR(100) NOT NULL,
    distance_m INT NOT NULL,
    duration_sec INT NOT NULL,
    traffic_score DECIMAL(6,2),
    control_score DECIMAL(6,2),
    hazard_score DECIMAL(6,2),
    accessibility_score DECIMAL(6,2),
    distance_score DECIMAL(6,2),
    total_score DECIMAL(6,2),
    score_breakdown_json JSON NOT NULL,
    disqualify_reason VARCHAR(500),
    route_path_json JSON NOT NULL,
    route_evaluation_id BIGINT NOT NULL REFERENCES route_evaluations(id)
);
COMMENT ON TABLE route_candidates IS '후보 경로 A/B/C';
COMMENT ON COLUMN route_candidates.id IS '후보 경로 ID';
COMMENT ON COLUMN route_candidates.route_name IS '경로명';
COMMENT ON COLUMN route_candidates.distance_m IS '거리(m)';
COMMENT ON COLUMN route_candidates.duration_sec IS '예상 이동 시간(초)';
COMMENT ON COLUMN route_candidates.traffic_score IS '교통 점수';
COMMENT ON COLUMN route_candidates.control_score IS '통제 점수';
COMMENT ON COLUMN route_candidates.hazard_score IS '위험 점수';
COMMENT ON COLUMN route_candidates.accessibility_score IS '접근성 점수';
COMMENT ON COLUMN route_candidates.distance_score IS '거리 점수';
COMMENT ON COLUMN route_candidates.total_score IS '총점';
COMMENT ON COLUMN route_candidates.score_breakdown_json IS '점수 세부 내역 JSON';
COMMENT ON COLUMN route_candidates.disqualify_reason IS '후보 제외 사유';
COMMENT ON COLUMN route_candidates.route_path_json IS '경로 좌표 JSON';
COMMENT ON COLUMN route_candidates.route_evaluation_id IS '경로 평가 ID';
CREATE TABLE notifications (
    id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    read_at TIMESTAMP WITHOUT TIME ZONE,
    created_at TIMESTAMP WITHOUT TIME ZONE NOT NULL DEFAULT CURRENT_TIMESTAMP,
    incidents_id BIGINT NOT NULL REFERENCES incidents(id),
    route_evaluation_id BIGINT NOT NULL REFERENCES route_evaluations(id),
    agency_id BIGINT NOT NULL REFERENCES agencies(id),
    user_id BIGINT NOT NULL REFERENCES users(id)
);
COMMENT ON TABLE notifications IS '사용자별 알림';
COMMENT ON COLUMN notifications.id IS '알림 ID';
COMMENT ON COLUMN notifications.read_at IS '읽은 일시';
COMMENT ON COLUMN notifications.created_at IS '생성 일시';
COMMENT ON COLUMN notifications.incidents_id IS '사건 ID · 원본 복수형 이름 유지';
COMMENT ON COLUMN notifications.route_evaluation_id IS '경로 평가 ID';
COMMENT ON COLUMN notifications.agency_id IS '기관 ID';
COMMENT ON COLUMN notifications.user_id IS '사용자 ID';
CREATE TABLE incident_support_requests (
    id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    incident_id BIGINT NOT NULL REFERENCES incidents(id),
    responder_id BIGINT NOT NULL REFERENCES users(id),
    support_type support_type_enum NOT NULL,
    request_content TEXT NOT NULL,
    created_at TIMESTAMP WITHOUT TIME ZONE NOT NULL DEFAULT CURRENT_TIMESTAMP,
    agency_id BIGINT NOT NULL REFERENCES agencies(id)
);
COMMENT ON TABLE incident_support_requests IS '추가 지원 요청';
COMMENT ON COLUMN incident_support_requests.id IS '추가 지원 요청 ID';
COMMENT ON COLUMN incident_support_requests.incident_id IS '사건 ID';
COMMENT ON COLUMN incident_support_requests.responder_id IS '요청 작성 사용자 ID';
COMMENT ON COLUMN incident_support_requests.support_type IS '요청 지원 유형';
COMMENT ON COLUMN incident_support_requests.request_content IS '추가 지원 요청 내용';
COMMENT ON COLUMN incident_support_requests.created_at IS '요청 시각';
COMMENT ON COLUMN incident_support_requests.agency_id IS '기관 ID';
COMMIT;